import subprocess
from pathlib import Path

def mirror_sha(mirror):
    return subprocess.run(["git", "-C", mirror, "rev-parse", "--short", "HEAD"], capture_output=True, text=True, check=True).stdout.strip()

def keep_resolvable(result, mirror):
    sha = mirror_sha(mirror)
    good = []
    for citation in result.get("citations", []):
        path, _, cited_sha = citation.removeprefix("rnd-kb/").partition("@")
        if cited_sha == sha and (Path(mirror) / path).is_file():
            good.append(citation)
    if not good:
        return {"answer": "I don't know. Ask in #engineering or check the brain index.", "citations": [], "unverified": []}
    return {**result, "citations": good}

def format_reply(result):
    cites = "\n".join(f"- {c}" for c in result["citations"])
    extra = "\nUnverified: " + "; ".join(result["unverified"]) if result.get("unverified") else ""
    return f"{result['answer']}\n\nSources:\n{cites}{extra}" if cites else result["answer"]
